WITH filtered_store_sales AS (SELECT * FROM store_sales WHERE sale_date < '2025-06-01'), summary AS (SELECT CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, product_id, MAX(revenue) AS max_revenue FROM filtered_store_sales GROUP BY CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END, product_id) SELECT sale_cohort, product_id, max_revenue FROM summary WHERE max_revenue < 1100 ORDER BY product_id, sale_cohort LIMIT 20;
